def segments_by_d(grid,color):
 pts={}
 for r,c in zip(*np.where(grid==color)):pts.setdefault(c-r,[]).append((r+c,r))
 result={}
 for d,arr in pts.items():
  us=sorted(u for u,r in arr); runs=[]; lo=prev=us[0]
  for u in us[1:]:
   if u!=prev+2: runs.append((lo,prev));lo=u
   prev=u
  runs.append((lo,prev));result[d]=runs
 return result
